#!/usr/bin/env python3
"""Development-time generator for the native C/AOT gamma-decode prototype.

Writes gamma_table.h: 256 source-embedded IEEE-754 float constants for
f32(pow(i/255.0, 2.2)) (the TeaVM/browser double-lowered variant). Hex float literals preserve
the exact 32-bit pattern. Run: python3 perfbench/native/gen_header.py [--check]
"""
import math
import os
import struct
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "gamma_table.h")


def f32(x):
    return struct.unpack("<f", struct.pack("<f", x))[0]


lines = [
    "/* Generated by perfbench/native/gen_header.py - DO NOT EDIT.",
    " * 256 deterministic float constants: f32(pow(i/255.0, 2.2)). Hex literals preserve bits.",
    " * Development-time source-embedded table; no runtime loop and no file loading.",
    " */",
    "#ifndef PERFBENCH_GAMMA_TABLE_H",
    "#define PERFBENCH_GAMMA_TABLE_H",
    "static const float GAMMA_2_2[256] = {",
]
for i in range(256):
    value = f32(math.pow(i / 255.0, 2.2))
    literal = value.hex() + "F"
    sep = "," if i != 255 else ""
    end = "\n" if (i + 1) % 4 == 0 else ""
    lines.append("    " + literal + sep + end)
lines += ["};", "#endif", ""]
content = "\n".join(lines)

if "--check" in sys.argv:
    if not os.path.exists(OUT) or open(OUT, "r", encoding="utf-8").read() != content:
        print("gamma_table.h is missing or differs from generator output", file=sys.stderr)
        sys.exit(1)
    print("gamma_table.h IDENTICAL")
else:
    with open(OUT, "w", encoding="utf-8") as f:
        f.write(content)
    print("wrote %s (%d bytes, 256 f32 constants)" % (OUT, len(content.encode())))
